      // mid-line AND overlaps the nav horizontally counts. Testing the hero\n      // alone missed dark cards scrolling underneath.\n      const onDark = this.inkOnDark();\n      if (hidden !== this.state.hdrHidden || solid !== this.state.hdrSolid || onDark !== this.state.onDark) {\n        this.setState({ hdrHidden: hidden, hdrSolid: solid, onDark: onDark });\n      }\n      this._lastY = y;\n    };\n    window.addEventListener('scroll', this._onScroll, { passive: true });\n    if (!(window.NR_BLOG_POSTS || []).length) this._postsT = setTimeout(() => this.forceUpdate(), 300);\n    setTimeout(() => this.initSparks(), 80);\n    this._onResize = () => { clearTimeout(this._rt); this._rt = setTimeout(() => this.initSparks(), 180); };\n    window.addEventListener('resize', this._onResize);\n  }\n\n  componentWillUnmount() {\n    window.removeEventListener('scroll', this._onScroll);\n    clearTimeout(this._postsT);\n    window.removeEventListener('resize', this._onResize);\n    cancelAnimationFrame(this._sparkRaf);\n    if (this._sparkIO) this._sparkIO.disconnect();\n    window.removeEventListener('resize', this._onSparkResize);\n  }\n\n  // Articles live in blog-posts.js so this page and the homepage stay in sync.\n  posts() {\n    return (typeof window !== 'undefined' && window.NR_BLOG_POSTS) || [];\n  }\n\n  featured() {\n    return this.posts().find(p => p.featured) || this.posts()[0] || {};\n  }\n\n  // Hero \"data flow\". The paths are not authored \u2014 they are read out of the\n  // artwork itself: a structure-tensor pass over the image yields, per cell,\n  // the dominant orientation (along the strand), how strongly oriented it is,\n  // and the local colour. Particles are seeded only on strand cells and are\n  // advected through that field, so every trail follows a real stream in the\n  // picture and wears its colour. Field is in image space and is projected\n  // through the object-fit: cover crop, so it stays aligned at any viewport.\n  async initSparks() {\n    cancelAnimationFrame(this._sparkRaf);\n    const cv = this.sparkRef.current, img = this.heroImgRef.current;\n    if (!cv || !img) return;\n    if (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;\n    const ctx = cv.getContext('2d');\n\n    if (!this._field) {\n      try {\n        const res = await fetch('assets/flow-field.json');\n        const j = await res.json();\n        const dec = (b) => { const s = atob(b), a = new Uint8Array(s.length); for (let i = 0; i < s.length; i++) a[i] = s.charCodeAt(i); return a; };\n        this._field = { w: j.w, h: j.h, ang: dec(j.ang), coh: dec(j.coh), r: dec(j.r), g: dec(j.g), b: dec(j.b) };\n      } catch (err) { return; }\n    }\n    const F = this._field, GW = F.w, GH = F.h;\n\n    // seed table: cells that actually sit on a strand, weighted by strength\n    const seeds = [];\n    for (let i = 0; i < F.coh.length; i++) if (F.coh[i] > 96) { seeds.push(i); if (F.coh[i] > 170) seeds.push(i); }\n    if (!seeds.length) return;\n\n    const sample = (u, v) => {\n      const x = Math.min(GW - 1, Math.max(0, u * GW)), y = Math.min(GH - 1, Math.max(0, v * GH));\n      const i = (y | 0) * GW + (x | 0);\n      return i;\n    };\n\n    let map = null;\n    const project = () => {\n      const W = cv.clientWidth, H = cv.clientHeight;\n      const dpr = Math.min(window.devicePixelRatio || 1, 2);\n      cv.width = W * dpr; cv.height = H * dpr;\n      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);\n      const iw = img.naturalWidth || 16, ih = img.naturalHeight || 9;\n      const sc = Math.max(W / iw, H / ih);\n      map = { w: iw * sc, h: ih * sc, x: (W - iw * sc) / 2, y: (H - ih * sc) / 2, W, H };\n    };\n    project();\n    this._onSparkResize = () => project();\n    window.addEventListener('resize', this._onSparkResize);\n\n    const spawn = (p) => {\n      const i = seeds[(Math.random() * seeds.length) | 0];\n      p.u = ((i % GW) + Math.random()) / GW;\n      p.v = (((i / GW) | 0) + Math.random()) / GH;\n      p.life = 0;\n      p.max = 1.6 + Math.random() * 2.8;\n      p.spd = 0.018 + Math.random() * 0.05;     // image widths per second\n      p.size = 0.7 + Math.random() * 1.5;\n      p.dx = 0; p.dy = 0;                        // heading, resolved on first step\n      const c = F.coh[i] / 255;\n      p.gain = 0.5 + c * 0.9;\n    };\n    const P = [];\n    for (let i = 0; i < 320; i++) { const p = {}; spawn(p); p.life = Math.random() * p.max; P.push(p); }\n\n    let last = 0;\n    const frame = (now) => {\n      const dt = last ? Math.min((now - last) / 1000, 0.05) : 0;\n      last = now;\n      ctx.globalCompositeOperation = 'destination-out';\n      ctx.fillStyle = 'rgba(0,0,0,.16)';\n      ctx.fillRect(0, 0, map.W, map.H);\n      ctx.globalCompositeOperation = 'lighter';\n\n      for (const p of P) {\n        const i = sample(p.u, p.v);\n        const strength = F.coh[i] / 255;\n        // left the strands, or lived long enough: respawn on a fresh one\n        if (strength < 0.3 || p.life > p.max || p.u < 0 || p.u > 1 || p.v < 0 || p.v > 1) { spawn(p); continue; }\n\n        const a = (F.ang[i] / 255) * Math.PI;     // 0..PI: orientation, not direction\n        let vx = Math.cos(a), vy = Math.sin(a);\n        // orientation is 180-ambiguous \u2014 keep travelling the way we already were\n        if (p.dx || p.dy) { if (vx * p.dx + vy * p.dy < 0) { vx = -vx; vy = -vy; } }\n        else if (Math.random() < 0.5) { vx = -vx; vy = -vy; }\n        p.dx = vx; p.dy = vy;\n\n        const u0 = p.u, v0 = p.v;\n        const step = p.spd * dt;\n        p.u += vx * step;\n        p.v += vy * step * (map.w / map.h);       // field is stored in image aspect\n        p.life += dt;\n\n        const x0 = map.x + u0 * map.w, y0 = map.y + v0 * map.h;\n        const x1 = map.x + p.u * map.w, y1 = map.y + p.v * map.h;\n        if (x1 < -40 || x1 > map.W + 40 || y1 < -40 || y1 > map.H + 40) continue;\n\n        // fade in and out over the particle's life\n        const t = p.life / p.max;\n        const fade = Math.min(1, t * 6) * Math.min(1, (1 - t) * 3.2);\n        const alpha = fade * p.gain * strength * 0.9;\n        const r = Math.min(255, F.r[i] + 60), g = Math.min(255, F.g[i] + 60), b = Math.min(255, F.b[i] + 60);\n        ctx.strokeStyle = 'rgba(' + r + ',' + g + ',' + b + ',' + alpha.toFixed(3) + ')';\n        ctx.lineWidth = p.size;\n        ctx.lineCap = 'round';\n        ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(x1, y1); ctx.stroke();\n        if (p.size > 1.6) {\n          ctx.fillStyle = 'rgba(' + r + ',' + g + ',' + b + ',' + (alpha * 0.45).toFixed(3) + ')';\n          ctx.beginPath(); ctx.arc(x1, y1, p.size * 1.35, 0, 6.283); ctx.fill();\n        }\n      }\n      this._sparkRaf = requestAnimationFrame(frame);\n    };\n\n    this._sparkIO = new IntersectionObserver((es) => {\n      const vis = es[0] && es[0].isIntersecting;\n      cancelAnimationFrame(this._sparkRaf);\n      if (vis) { last = 0; this._sparkRaf = requestAnimationFrame(frame); }\n    }, { threshold: 0 });\n    this._sparkIO.observe(cv);\n  }\n\n\n  inkOnDark() {\n    const BAND = 46;\n    const nav = this._navEl || (this._navEl = document.querySelector('header nav'));\n    const nr = nav ? nav.getBoundingClientRect() : { left: 0, right: window.innerWidth };\n    const els = document.querySelectorAll('[data-hdr-dark]');\n    for (const el of els) {\n      const r = el.getBoundingClientRect();\n      if (r.width < 40 || r.height < 20) continue;\n      if (r.top > BAND || r.bottom < BAND) continue;\n      if (r.right < nr.left || r.left > nr.right) continue;\n      return true;\n    }\n    return false;\n  }\n\n  renderVals() {\n    const p = this.props;\n    const dark = this.state.onDark;\n    return {\n      menuOpen: this.state.menuOpen,\n      openMenu: () => this.setState({ menuOpen: true }),\n      closeMenu: () => this.setState({ menuOpen: false }),\n      heroRef: this.heroRef,\n      heroImgRef: this.heroImgRef,\n      sparkRef: this.sparkRef,\n      // 12 cards at a time; \"Load more\" adds the next batch on the same page\n      ...(() => {\n        const q = (this.state.query || '').trim().toLowerCase();\n        // while searching, the featured article is part of the results too\n        const all = (p.posts && p.posts.length ? p.posts : this.posts())\n          .filter(x => q ? [x.title, x.excerpt, x.category].join(' ').toLowerCase().includes(q) : !x.featured);\n        const n = Math.min(all.length, this.state.shown || 12);\n        return {\n          posts: all.slice(0, n),\n          hasMore: n < all.length,\n          shownCount: n,\n          totalCount: all.length,\n          loadMore: () => this.setState(s => ({ shown: (s.shown || 12) + 12 })),\n          query: this.state.query || '',\n          onQuery: (e) => this.setState({ query: e.target.value, shown: 12 }),\n          noResults: !!q && all.length === 0\n        };\n      })(),\n      featured: this.featured(),\n      hasArticles: this.posts().length > 0,\n      noArticles: this.posts().length === 0,\n      // summary stays collapsed until hover or focus, matching the grid cards\n      featRow: this.state.featOpen ? '1fr' : '0fr',\n      featEnter: () => this.setState({ featOpen: true }),\n      featLeave: () => this.setState({ featOpen: false }),\n      themeVars: {\n        '--teal': p.teal || '#17726B',\n        '--hdrY': this.state.hdrHidden ? '-120%' : '0px',\n        '--hdrBlur': this.state.hdrSolid ? 'blur(14px)' : 'none',\n        '--hdrInk': dark ? '#fff' : (p.teal || '#17726B'),\n        '--hdrShadow': dark ? '0 1px 12px rgba(0,0,0,.55)' : 'none'\n      }\n    };\n  }\n}\n\n\n;NR.boot(Component, {\"teal\": \"#17726B\"});\n})();\n</script>\n</body>\n</html>\n";
